xpath.script:
window.MathJax = window.MathJax || {
    tex: {
        inlineMath: [['$', '$'], ['\\(', '\\)']],
        displayMath: [['$$', '$$'], ['\\[', '\\]']],
        processEscapes: true
    },
    svg: { fontCache: 'global' },
    options: { skipHtmlTags: ['script', 'noscript', 'style', 'textarea', 'pre', 'code'] }
};

// Survey navigates between pages via AJAX (no full reload), so
// re-typeset whenever the question container is replaced.
document.addEventListener('DOMContentLoaded', function () {
    var root = document.querySelector('.o_survey_form');
    if (!root || !window.MutationObserver) return;
    var pending;
    new MutationObserver(function () {
        clearTimeout(pending);
        pending = setTimeout(function () {
            if (window.MathJax && window.MathJax.typesetPromise) {
                window.MathJax.typesetPromise([root]).catch(function () {});
            }
        }, 150);
    }).observe(root, { childList: true, subtree: true });
});

div.script:
(function(){
    var root = document.querySelector('.tvbo-landing');
    if(!root) return;
    if(!('IntersectionObserver' in window)) return;
    root.classList.add('reveal-on');
    var io = new IntersectionObserver(function(entries){
        entries.forEach(function(en){ if(en.isIntersecting){ en.target.classList.add('in'); io.unobserve(en.target); } });
    }, { rootMargin: '0px 0px -8% 0px', threshold: 0.08 });
    root.querySelectorAll('.reveal').forEach(function(e){ io.observe(e); });

    // In-action clips: nudge the speed up, and only play the clip
    // that's on screen so several don't decode at once.
    var clips = root.querySelectorAll('video.clip');
    clips.forEach(function(v){
        var speed = function(){ try { v.playbackRate = 1.5; } catch(e){} };
        v.addEventListener('loadedmetadata', speed); speed();
    });
    var vio = new IntersectionObserver(function(entries){
        entries.forEach(function(en){
            if(en.isIntersecting){ if(en.target.play){ en.target.play().catch(function(){}); } }
            else { if(en.target.pause){ en.target.pause(); } }
        });
    }, { threshold: 0.25 });
    clips.forEach(function(v){ vio.observe(v); });
})();

window.MathJax = {
    tex: {
        inlineMath: [['$', '$'], ['\\(', '\\)']],
        displayMath: [['$$', '$$'], ['\\[', '\\]']],
        processEscapes: true,
        processEnvironments: true
    },
    svg: { fontCache: 'global', scale: 1 }
};

(function(){
    var root = document.querySelector('.tvbo-landing');
    if(!root) return;
    if(!('IntersectionObserver' in window)) return;
    root.classList.add('reveal-on');
    var io = new IntersectionObserver(function(entries){
        entries.forEach(function(en){ if(en.isIntersecting){ en.target.classList.add('in'); io.unobserve(en.target); } });
    }, { rootMargin: '0px 0px -8% 0px', threshold: 0.08 });
    root.querySelectorAll('.reveal').forEach(function(e){ io.observe(e); });

    // In-action clips: nudge the speed up, and only play the clip
    // that's on screen so several don't decode at once.
    var clips = root.querySelectorAll('video.clip');
    clips.forEach(function(v){
        var speed = function(){ try { v.playbackRate = 1.5; } catch(e){} };
        v.addEventListener('loadedmetadata', speed); speed();
    });
    var vio = new IntersectionObserver(function(entries){
        entries.forEach(function(en){
            if(en.isIntersecting){ if(en.target.play){ en.target.play().catch(function(){}); } }
            else { if(en.target.pause){ en.target.pause(); } }
        });
    }, { threshold: 0.25 });
    clips.forEach(function(v){ vio.observe(v); });
})();
